class Solution:
    def captureForts(self, forts: List[int]) -> int:
        n = len(forts)
        ans = 0
        for i in range(n):
            if forts[i] == 0:
                continue
            for d in (-1, 1):
                j, c = i + d, 0
                while 0 <= j < n and forts[j] == 0:
                    c += 1
                    j += d
                if 0 <= j < n and forts[j] == -forts[i]:
                    ans = max(ans, c)
        return ans

