class Solution {
public:
    int captureForts(vector<int>& forts) {
        int n = forts.size(), ans = 0;
        for (int i = 0; i < n; i++) {
            if (forts[i] == 0) continue;
            for (int d : {-1, 1}) {
                int j = i + d, c = 0;
                while (j >= 0 && j < n && forts[j] == 0) { c++; j += d; }
                if (j >= 0 && j < n && forts[j] == -forts[i]) ans = max(ans, c);
            }
        }
        return ans;
    }
};

