class Solution:
    def captureForts(self, forts: List[int]) -> int:
        ans, prev = 0, -1
        for i, x in enumerate(forts):
            if x != 0:
                if prev != -1 and forts[prev] != x:
                    ans = max(ans, i - prev - 1)
                prev = i
        return ans

